/// A new scroll pushing against an end: which way, and how far past it, as
/// of `at`, draining away once the scrolling pauses.
#[derive(Clone, Copy)]
struct ScrollPush {
    up: bool,
    amount: f32,
    at: Instant,
}

impl Default for ScrollPush {
    fn default() -> Self {
        Self {
            up: false,
            amount: 0.,
