        if self.task_history.expanded {
            let rows = &self.task_history.rows;
            !up && rows.offset().y <= -rows.max_offset().y + px(1.)
        } else {
            up && self.tasks.len() >= 2 && self.output_table.scroll().offset().y >= -px(1.)
        }
    }

