    let mut stopped = PromptTask::new("Do it".into());
    stopped.set_compiled(super::Compiled::new("Prompt_2".into(), "Do it".into()));
    stopped.apply(tool("t1", "Bash"));
    stopped.end();
    assert_eq!(stopped.status, TaskStatus::Failed);
    assert!(matches!(
